import logging
from collections import OrderedDict, defaultdict
import csv
import io
import re

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Element(OrderedDict):
    def __getattr__(self, name):
        if not name.startswith('_') and name in self:
            return self[name]
        raise AttributeError(
            "'{type_}' object has no attribute '{attribute}'".format(
                type_=type(self).__name__,
                attribute=name))

    def get_re(self, regex):
        return self[
            next(key for key in self.keys() if re.search(regex, key))]


class GetSystemResources(object):

    @staticmethod
    def _replace_field_name(field_name, repls):
        for match, repl in repls.items():
            field_name = re.sub(match, repl, field_name)
        return field_name

    def execute_with_csv(self, name, command, headers=None):
        """
        Return processed csv data from AaShell terminal for given command.

        :param str name: AaShell CLI alias name
        :param str command: command need to be executed to get csv format data with delimiter ';'
        :param list headers: (optional) list of header processing details. Processing details can be in form of list or
                            dict based on requirement. List will be used for using new headers, and dict will be used
                            for replacing existing headers from output for key (regex match) with value (replacement
                            string)
        :rtype: list
        :return: list of list of Element objects
            Example::

                [
                    [Element([('time stamp', '2023-02-01T16:04:35.303230Z'),
                        ('Cpu0 idle[%]', '97.9'),
                        ('Cpu0 user[%]', '0.0'),
                        ('Cpu0 system[%]', '2.0'),
                        ...])],
                    [Element([('PID', '14056'),
                        ('ProcessName', 'em_main'),
                        ('CPU Average', '102.74'),
                        ('User mode CPU Average', '102.74'),
                        ('Kernel mode CPU Average', '0.00'),
                        ('CPU avg total [%]', '0.00')]),
                    Element([('PID', '14123'),
                        ('ProcessName', 'em_main'),
                        ('CPU Average', '101.76'),
                        ('User mode CPU Average', '101.76'),
                        ('Kernel mode CPU Average', '0.00'),
                        ('CPU avg total [%]', '0.00')]),
                    ...]
                ]
        """
        system_resources_output = self.execute_aashell_command(
            name=name,
            command=command)
        tables = []
        for index, paragraph in enumerate(
                filter(
                    None,
                    re.split(r"\n{2,}|\n\Z|\A\n", system_resources_output))):
            replace_header, add_header = False, False
            if headers and headers[index]:
                replace_header = isinstance(headers[index], dict)
                add_header = isinstance(headers[index], list)
            csv_reader = csv.DictReader(
                io.StringIO(paragraph),
                fieldnames=headers[index] if add_header else None,
                delimiter=";")
            if replace_header:
                csv_reader.fieldnames = [
                    self._replace_field_name(field_name, headers[index])
                    for field_name in csv_reader.fieldnames]
            tables.append([
                Element((field, row[field]) for field in csv_reader.fieldnames if field)
                for row in csv_reader])
        return tables

    def get_system_resources(self, name):
        """
        Return System Resources or AaShell 'sysinfo -n' command output. Return is list for Element(s) where
        fields of an element can by accessed as:

            - element.metric_name
            - element.node_id
            - element.metric_value

        Note: This keyword is deprecated, use get_sysinfo() instead. For specific resource info, use
        filter keywords system_info(), process_info() or cgroup_info().

        :param str name: AaShell CLI alias name

        :rtype: list
        :return: list of Element objects
            Example::

              [Element([('node_id', '0x1011'), ('metric_name', 'System UsedMemory [k]'), ('metric_value', '1220452')]),
              Element([('node_id', '0x1011'), ('metric_name', 'System SUnreclaim [kB]'), ('metric_value', '55208')])
              ...]
        """
        logger.warning("This keyword is deprecated, use get_sysinfo() instead."
                       " For specific resource info, use filter keywords "
                       " system_info(), process_info() or cgroup_info() keywords.")
        return self.execute_with_csv(
            name=name,
            command="sysinfo -n",
            headers=[['node_id', 'metric_name', 'metric_value']])[0]

    def get_sysinfo(self, name):
        """
        Return System Resources or AaShell 'sysinfo -nh' command output. Return is list of info_group where info_group
        is list of Element(s).

        :param str name: AaShell CLI alias name

        :rtype: list
        :return: list of list of Element objects
            Example::

                [
                    [Element([('nid', '0x1011'), ('name', 'System UsedMemory [k]'), ('value[kb]', '1220452')]),
                    Element([('nid', '0x1011'), ('name', 'System SUnreclaim [kB]'), ('value[kb]', '55208')])
                    ...]
                ]
        """
        return self.execute_with_csv(
            name=name,
            command="sysinfo -nh")

    def _merge_groups(self, info_groups):
        merged_groups = defaultdict(list)
        for info_group in info_groups:
            key = tuple(info_group[0].keys())
            merged_groups[key].extend(info_group)
        return list(merged_groups.values())

    def _filter_info(self, info_groups, header_identifier_function):
        matched_group = []
        for info_group in info_groups:
            if header_identifier_function(list(info_group[0].keys())):
                matched_group.append(info_group)
        return matched_group

    def system_info(self, info_groups):
        """
        Extract system info from info_groups.

        :param list[list[Element]] info_groups: list of info groups as returned by get_sysinfo()

        :rtype: list
        :return: list of Element objects
            Example::

                [Element([('NID', '0x223d'), ('Name', 'SUnreclaim [kB]'), ('Value [kB]', '132140')]),
                 Element([('NID', '0x223d'), ('Name', 'Active(file) [kB]'), ('Value [kB]', '109640')])
                ...]
        :raises IndexError: if no system info is found
        """

        def header_identification_function(keys):
            return "ProcessInfo" not in keys and "CgroupInfo" not in keys
        return self._merge_groups(self._filter_info(info_groups, header_identification_function))[0]

    def process_info(self, info_groups):
        """
        Extract process info from info_groups.

        :param list[list[Element]] info_groups: list of info groups as returned by get_sysinfo()

        :rtype: list
        :return: list of Element objects
            Example::

                [Element([('NID', '0x223d'), ('ProcessInfo', 'ProcessInfo'), ('PID', '31800'), ...]),
                 Element([('NID', '0x223d'), ('ProcessInfo', 'ProcessInfo'), ('PID', '31677'), ...])
                ...]
        :raises IndexError: if no process info is found
        """
        def header_identification_function(keys):
            return "ProcessInfo" in keys
        return self._merge_groups(self._filter_info(info_groups, header_identification_function))[0]

    def cgroup_info(self, info_groups):
        """
        Extract cgroup info from info_groups.

        :param list[list[Element]] info_groups: list of info groups as returned by get_sysinfo()

        :rtype: list
        :return: list of Element objects
            Example::

                [Element([('NID', '0x1021'), ('CgroupInfo', 'CgroupInfo'), ('Cgroup', '/'), ...]),
                 Element([('NID', '0x1021'), ('CgroupInfo', 'CgroupInfo'), ('Cgroup', '/apps.slice'), ...])
                ...]
        :raises IndexError: if no cgroup info is found
        """
        def header_identifier_function(keys):
            return "CgroupInfo" in keys
        return self._merge_groups(self._filter_info(info_groups, header_identifier_function))[0]
